  // the bounding box of a detail (its lines & texts)
  function bbox(g) {
    if (g.bb) return g.bb;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    const at = (x, y) => { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; };
    for (const p of g.p.concat(g.f)) for (let i = 2; i < p.length; i += 2) at(p[i], p[i + 1]);
    for (const t of g.t) { const w = t[2].length * t[3] * 0.62; at(t[0] - (t[5] === 'end' ? w : t[5] === 'middle' ? w / 2 : 0), t[1] - t[3]); at(t[0] + (t[5] === 'start' ? w : t[5] === 'middle' ? w / 2 : 0), t[1]); }
    return (g.bb = { x: x0, y: y0, w: x1 - x0, h: y1 - y0 });
  }
  // draw one detail with its top-left at (ox, oy); k = drawing units -> output units
  AP.drawPlumbDet = function (d, key, ox, oy, k, ts) {
    const g = AP.PLUMB_DET[key], b = bbox(g), X = x => ox + (x - b.x) * k, Y = y => oy + (y - b.y) * k;
    for (const f of g.f) { const pts = []; for (let i = 2; i < f.length; i += 2) pts.push([X(f[i]), Y(f[i + 1])]); d.poly(pts, true, { fill: '#000000', w: 0.05 * ts, layer: 'DETAIL' }); }
    for (const p of g.p) {
      const pts = []; for (let i = 2; i < p.length; i += 2) pts.push([X(p[i]), Y(p[i + 1])]);
      const s = { w: p[1] * ts, layer: 'DETAIL' };
      if (pts.length === 2) d.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1], s); else d.poly(pts, !!p[0], s);
    }
    for (const t of g.t) d.text(X(t[0]), Y(t[1]), t[2], t[3] * k, { anchor: t[5], v: t[6] === 'base' ? undefined : t[6], rot: -t[4] });
    return { w: b.w * k, h: b.h * k };
  };
  AP.plumbDetSize = key => { const b = bbox(AP.PLUMB_DET[key]); return { w: b.w, h: b.h }; };
